// RUN: %check_clang_tidy -std=c++23-or-later %s malterlib-thread-local-storage,malterlib-coroutine-thread-local-reference %t -- -config="{CheckOptions: {malterlib.OptionsFile: '%S/Inputs/ClangTidyOptions.yaml', malterlib-thread-local-storage.ThreadLocalFunctions: 'fg_GetCurrent'}}" -- -I %S/Inputs

// This file is generated by gen_thread_local.py: what a getter gives is told
// by the accessors of the check that asks, not by another check's.
#include "malterlib-actor-phase.h"

TCFuture<int> fg_Work();
int &fg_GetCurrent();
inline int &fg_Getter() {
  return fg_GetCurrent();
// CHECK-MESSAGES: :[[@LINE-1]]:10: warning: a reference to thread-local data is returned as a type that isn't a reference to a thread-local type
}
int *g_pValue;
inline void fg_Store() {
  g_pValue = &fg_Getter();
// CHECK-MESSAGES: :[[@LINE-1]]:14: warning: a pointer to thread-local data is stored in the variable 'g_pValue'
}
TCFuture<int> fg_Coroutine() {
  int &Value = fg_Getter();
  co_await fg_Work();
  co_return Value;
}
